// The question, the columns the view must return, the business definitions and the clean schema.
// No data rows are sent, and the reference SQL (the answer key) is never shown to the agent.
const q = $('Each question').first().json;
const stored = $('Get stored SQL').first().json;
const prompt = [
  `Question: ${q.question}`,
  `View: models.${q.view}`,
  'Columns the view must return (name, type, meaning):',
  ...Object.entries(q.columns).map(([c, [type, meaning]]) => `- ${c} (${type}): ${meaning}`),
  q.grain.length ? `One row per ${q.grain.join(', ')}.` : 'Exactly one row.',
  q.notes,
  '',
  'Business definitions:',
  ...q.definitions.map(d => `- ${d}`),
  '',
  'Tables:',
  $('Get schema').first().json.schema_text,
  '',
  'How the tables link:',
  ...q.relationships.map(r => `- ${r}`),
].filter(line => line !== '').join('\n');
// The agent is asked only when there is no SQL that passed before, the spec changed, or FRESH_SQL is on
const needsSql = q.fresh_sql || !stored.select_sql || stored.spec_hash !== q.spec_hash;
return [{ json: { prompt, needs_sql: needsSql, stored_run_id: stored.run_id ?? null } }];

// Use the SQL that passed in an earlier run (no AI call). It still goes through the guardrails and is validated
// again on today's clean data.
const s = $('Get stored SQL').first().json;
return [{ json: { origin: 'stored', output: { select_sql: s.select_sql, explanation: s.explanation,
                                              assumptions: s.assumptions ?? [] } } }];

// Guardrails (deterministic, no AI): the SQL must be one read-only SELECT on the clean schema. Then build the script
// that creates the view in models as the restricted role transform_agent and validates it, in one transaction.
const q = $('Each question').first().json;
const out = $input.first().json;
const origin = out.origin ?? 'agent';
const answer = out.output ?? {};
const lit = v => `'${String(v).replace(/'/g, "''")}'`;
const select = String(answer.select_sql ?? '').trim().replace(/;\s*$/, '');
const found = re => [...new Set((select.match(re) ?? []).map(w => w.toLowerCase().replace(/\s+/g, '')))];

const problems = [];
if (!select) {
  problems.push(out.error ? `the agent failed: ${out.error.message ?? out.error}` : 'no SQL was returned');
} else {
  if (!/^(select|with)\b/i.test(select)) problems.push('it must start with SELECT or WITH');
  if (select.includes(';')) problems.push('it must be a single statement (no semicolons)');
  if (/--|\/\*/.test(select)) problems.push('it must not contain comments');
  const writes = found(/\b(insert|update|delete|merge|drop|alter|create|grant|revoke|truncate|copy|call|do|execute|vacuum|analyze|refresh|lock|comment|set|reset|listen|notify|prepare|into)\b/gi);
  if (writes.length) problems.push(`it must only read data (found: ${writes.join(', ')})`);
  const schemas = found(/\b(raw|ops|cleaning|transform|models|analytics|public|auth|storage|extensions|vault|pg_catalog|information_schema)\s*\./gi);
  if (schemas.length) problems.push(`it may only read the clean schema (found: ${schemas.join(', ')})`);
  if (/\bpg_\w+|\b(current_setting|set_config|dblink\w*|lo_\w+)\s*\(/i.test(select)) problems.push('it must not use system functions');
  if (!/\bclean\s*\./i.test(select)) problems.push('it must read from the clean schema (write clean.<table>)');
  if (select.length > 12000) problems.push('it is too long (over 12,000 characters)');
}

const V = `models.${q.view}`;
const viewSql = `create view ${V} as\n${select}`;
const script = problems.length
  ? `do $guard$ begin raise exception 'guardrail: %', ${lit(problems.join('; '))}; end $guard$;`
  : [
      `set local statement_timeout = '120s';`,
      `set local role transform_agent;`,
      `drop view if exists ${V};`,
      `${viewSql};`,
      `reset role;`,
      `select transform.validate_view(${lit(q.view)}, ${lit(JSON.stringify(q.spec))}::jsonb) as result;`,
    ].join('\n');
return [{ json: { origin, attempt: 1, select_sql: select, view_sql: problems.length ? null : viewSql,
                  explanation: answer.explanation ?? null, assumptions: answer.assumptions ?? [],
                  guardrail_problems: problems, script } }];

