// Turn the outcome into an ops.transform_models row and an ops.agent_logs row. The SQL is logged either way (FR-T5).
const q = $('Each question').first().json;
const c = $('Check SQL').first().json;
const out = $input.first().json;
const lit = v => `'${String(v).replace(/'/g, "''")}'`;
const error = out.result ? null : String(out.message ?? out.error?.message ?? out.error ?? 'no result');
let result = out.result ?? null;
if (!result && error.includes('view failed validation: ')) {
  try { result = JSON.parse(error.slice(error.indexOf('{'))); } catch (e) { result = null; }
}
const passed = result?.passed === true;
const checks = result?.checks ?? [];
const failed = checks.filter(x => !x.passed);
const why = passed ? null
  : failed.length ? failed.map(x => `${x.check}: ${x.detail}`).join('; ')
  : error.replace(/^guardrail: /, 'guardrail: the SQL was not run because ');
const final = passed || c.attempt === 2;
const from = { agent: 'the agent', repair: "the agent's repair", stored: 'an earlier run' }[c.origin];

const model = {
  model_id: `${q.run_id}:${q.view}:${c.attempt}`, run_id: q.run_id, view_name: q.view, question: q.question,
  spec_hash: q.spec_hash, attempt: c.attempt, origin: c.origin, select_sql: c.select_sql, view_sql: c.view_sql,
  explanation: c.explanation, assumptions: c.assumptions, status: passed ? 'passed' : 'failed',
  checks: result?.checks ?? null, error: why,
};
const log = {
  run_id: q.run_id, agent: 'transformation', action: 'build_view', source: q.view, target_table: `models.${q.view}`,
  status: passed ? 'success' : final ? 'failed' : 'warning', rows_read: null, rows_written: result?.row_count ?? null,
  duration_ms: null,
  reason: passed
    ? `models.${q.view} created from SQL by ${from}: ${result.row_count} row${result.row_count === 1 ? '' : 's'}, all ${checks.length} checks passed`
    : `SQL by ${from} for models.${q.view} was rejected, the view is unchanged: ${why}` +
      (final ? '' : '. The agent gets one try to fix it.'),
  details: { attempt: c.attempt, origin: c.origin, sql: c.view_sql ?? c.select_sql, explanation: c.explanation,
             assumptions: c.assumptions, checks: result?.checks ?? null },
};
const insert = (table, row) => {
  const cols = Object.keys(row);
  return `insert into ${table} (${cols.join(', ')}) select ${cols.join(', ')} ` +
         `from jsonb_populate_record(null::${table}, ${lit(JSON.stringify(row))}::jsonb);`;
};
return [{ json: {
  passed, final, why, attempt: c.attempt, view: q.view,
  examples: failed.find(x => x.check === 'matches reference')?.examples ?? [],
  save_sql: `${insert('ops.transform_models', model)}\n${insert('ops.agent_logs', log)}\nselect 1 as saved;`,
} }];

// One second chance (FR-T4): the agent sees its SQL and exactly why it was rejected
const r = $('Read result').first().json;
const prompt = [
