  $('Check SQL').first().json.select_sql || '(no SQL)',
  '',
  `Why: ${r.why}`,
  r.examples.length ? `Rows that differ (what your view returned → what was expected):\n${JSON.stringify(r.examples)}` : '',
  '',
  'Write corrected SQL that fixes this, following all the instructions above.',
].join('\n');
return [{ json: { prompt } }];

