const log = {
  run_id: q.run_id, agent: 'transformation', action: 'build_view', source: q.view, target_table: `models.${q.view}`,
  status: passed ? 'success' : final ? 'failed' : 'warning', rows_read: null, rows_written: result?.row_count ?? null,
  duration_ms: null,
  reason: passed
    ? `models.${q.view} created from SQL by ${from}: ${result.row_count} row${result.row_count === 1 ? '' : 's'}, all ${checks.length} checks passed`
    : `SQL by ${from} for models.${q.view} was rejected, the view is unchanged: ${why}` +
      (final ? '' : '. The agent gets one try to fix it.'),
  details: { attempt: c.attempt, origin: c.origin, sql: c.view_sql ?? c.select_sql, explanation: c.explanation,
             assumptions: c.assumptions, checks: result?.checks ?? null },
};
const insert = (table, row) => {
  const cols = Object.keys(row);
  return `insert into ${table} (${cols.join(', ')}) select ${cols.join(', ')} ` +
         `from jsonb_populate_record(null::${table}, ${lit(JSON.stringify(row))}::jsonb);`;
};
