  passed, final, why, attempt: c.attempt, view: q.view,
  examples: failed.find(x => x.check === 'matches reference')?.examples ?? [],
  save_sql: `${insert('ops.transform_models', model)}\n${insert('ops.agent_logs', log)}\nselect 1 as saved;`,
} }];

// FR-T4: a view that still fails after the repair try stops the run
const q = $('Each question').first().json;
const r = $('Read retry result').first().json;
return [{ json: {
  run_id: q.run_id, agent: 'transformation', action: 'run_complete', source: null, target_table: null,
  status: 'failed', rows_read: null, rows_written: null, duration_ms: null,
  reason: `Stopped: models.${q.view} failed validation twice (${r.why}). Nothing was published: the analytics ` +
          'tables still hold the last good run.',
  details: JSON.stringify({ view: q.view, why: r.why }),
} }];

// Every view passed: publish them all as analytics tables. One script, so one transaction: the dashboard switches
// from the last good run to this one in a single step, never a mix of both.
const lit = v => `'${String(v).replace(/'/g, "''")}'`;
const sql = $('Questions').all().map(i => i.json).map(q =>
  `select ${lit(q.view)} as table_name, transform.publish(${lit(q.view)}, ${lit(q.run_id)}, ` +
  `${lit(JSON.stringify(q.indexes ?? []))}::jsonb) as row_count;`).join('\n');
return [{ json: { sql } }];

const run = $('Questions').first().json;
const views = $input.all().map(i => i.json).filter(v => v.view_name);
const repaired = views.filter(v => v.attempt === 2).length;
const published = $('Publish tables').all().map(i => i.json);
return [{ json: {
  run_id: run.run_id, agent: 'transformation', action: 'run_complete', source: null, target_table: null,
  status: 'success', rows_read: null, rows_written: published.length, duration_ms: null,
  reason: `${views.length} views validated (` + views.map(v => `${v.view_name}: ${v.origin}`).join(', ') + ')' +
          (repaired ? `, ${repaired} after the agent's repair try` : '') + '. Published to analytics: ' +
          published.map(p => `${p.table_name} ${p.row_count} rows`).join(', '),
  details: JSON.stringify({ views: views.map(v => ({ view: v.view_name, origin: v.origin, attempt: v.attempt })),
                            published }),
} }];
